INSERT INTO _q26_notes (sub, kind, sort_order, text_ar, depth, page) VALUES
  ('1.1.1', 'guidance', 1, 'تتضمن الرؤية والرسالة توجهاً يعكس القيم التربوية والثقافية والوطنية، ويتوافق مع توجهات الدولة وسياساتها التعليمية.', 1, 35),
  ('1.1.1', 'guidance', 2, 'تعبر الرؤية والرسالة عن مواءمة واضحة بين الكفايات المحلية والعالمية في بناء شخصية المتعلم.', 1, 35),
  ('1.1.1', 'guidance', 3, 'وضوح الرؤية والرسالة يشمل دقة صياغتها، واتساقها، وتوضيحها للأطراف المعنية ومعرفتهم بها وبأدوارهم في تحقيقها.', 1, 35),
  ('1.1.1', 'guidance', 4, 'نشر الرؤية والرسالة بشكلٍ واضح (في المبنى المدرسي، على الموقع الإلكتروني، وسائل التواصل الاجتماعي، الوثائق الرسمية، الاجتماعات ... إلخ)', 1, 35),
  ('1.1.1', 'guidance', 5, 'عرض الرؤية والرسالة والقيم باللغة العربية واللغات المستخدمة في المدرسة.', 1, 35),
  ('1.1.1', 'guidance', 6, 'توعية الأطراف المعنية بأدوارهم في المساهمة الفعلية في تحقيق الرؤية والرسالة، من خلال اللقاءات، والأنشطة، ووسائل التواصل الاجتماعي للمدرسة.', 1, 35),
  ('1.1.1', 'guidance', 7, 'أهداف المدرسة يجب أن تكون:', 1, 35),
  ('1.1.1', 'guidance', 8, 'واضحة ومحددة، وقابلة للقياس والتنفيذ ضمن إطار زمني محدد.', 2, 36),
  ('1.1.1', 'guidance', 9, 'مرتبطة ارتباطاً مباشراً بالرؤية والرسالة.', 2, 36),
  ('1.1.1', 'guidance', 10, 'تسهم في تحويل الرؤية والرسالة إلى ممارسات تربوية واقعية.', 2, 36),
  ('1.1.1', 'reflection', 1, 'ما هي طرق ووسائل نشر وتوضيح رؤية ورسالة وقيم المدرسة؟', NULL, 35),
  ('1.1.1', 'reflection', 2, 'ما مدى وعي الأطراف المعنية بالرؤية والرسالة والقيم؟ وكيف يتم قياس ذلك؟', NULL, 35),
  ('1.1.1', 'reflection', 3, 'ما مدى توافق الرؤية والرسالة القيم والأهداف مع توجهات الدولة وسياساتها التعليمية؟ كيف تم قياس ذلك؟', NULL, 35),
  ('1.1.1', 'reflection', 4, 'كيف يتم التأكد من أن الأهداف قابلة للقياس والتنفيذ، وتخدم فعلياً التوجه العام للمدرسة؟', NULL, 35),
  ('1.1.1', 'reflection', 5, 'ما مدى انعكاس الرؤية والرسالة والقيم على السياسات والقرارات والممارسات التعليمية؟', NULL, 35),
  ('1.1.2', 'guidance', 1, 'الموارد المادية: المبنى المدرسي ومرافقه، وجاهزيته بالأدوات والموارد والمصادر الكافية والمناسبة والتي تحقق رؤية ورسالة المدرسة وأهدافها مثل الفصول الدراسية، المختبرات، المرافق الرياضية، والتقنيات التعليمية، الموارد والأدوات والمصادر التعليمية، ولا يوجد عجز في المصادر يؤثر على تحقيقهم.', 1, 36),
  ('1.1.2', 'guidance', 2, 'الموارد البشرية: العاملون في المدرسة ذوو كفاءة ومؤهلون، مثل: القيادة المدرسية، الأكاديميون، الإداريون، ولا يوجد عجز أو نواقص تؤثر على تحقيق الرؤية والرسالة.', 1, 36),
  ('1.1.2', 'guidance', 3, 'الوضع المالي: الحالة العامة للموارد المالية المتاحة في المدرسة ومدى قدرتها على تغطية احتياجاتها والأولويات التعليمية والتربوية.', 1, 36),
  ('1.1.2', 'guidance', 4, 'توزيع الموارد المالية لضمان توافقها مع احتياجات المدرسة والأولويات التعليمية والتربوية.', 1, 36),
  ('1.1.2', 'reflection', 1, 'ما مدى مواءمة المبنى والمرافق والتجهيزات مع رؤية المدرسة ورسالتها وأهدافها؟ وكيف يمكن تحسينها لضمان دعم أفضل لتحقيقهم؟', NULL, 36),
  ('1.1.2', 'reflection', 2, 'هل توجد خطط لتطوير أو تحسين البنية التحتية بما يخدم التوجه المستقبلي للمدرسة؟', NULL, 36),
  ('1.1.2', 'reflection', 3, 'هل تتناسب مؤهلات وخبرات الكوادر البشرية مع متطلبات الرؤية والرسالة المدرسية؟', NULL, 36),
  ('1.1.2', 'reflection', 4, 'كيف تسهم الموارد البشرية الحالية في تحقيق أهداف المدرسة؟', NULL, 36),
  ('1.1.2', 'reflection', 5, 'هل توجد فجوات في الكوادر البشرية تؤثر على تنفيذ الرؤية والرسالة؟', NULL, 36),
  ('1.1.2', 'reflection', 6, 'ما مدى كفاية الموارد المادية والمالية لضمان جودة التعليم وتنفيذ البرامج والأنشطة بما يحقق رسالة وأهداف المدرسة؟', NULL, 36),
  ('1.1.3', 'guidance', 1, 'المراجعة: عملية تقويم دورية تستند إلى بيانات أداء المدرسة ومخرجاتها واحتياجاتها الفعلية، والتغيرات المحلية والعالمية المحيطة بها.', 1, 36),
  ('1.1.3', 'guidance', 2, 'الاستفادة من عملية المراجعة في التحديث (ان تطلبت الحاجة) وفقاً لاحتياجات المدرسة ومخرجاتها الأكاديمية والتربوية والسلوكية، وتحدياتها.', 1, 37),
  ('1.1.3', 'guidance', 3, 'ربط عملية المراجعة والتحديث بتوجهات الدولة والسياسات الوطنية والتغيرات العالمية.', 1, 37),
  ('1.1.3', 'guidance', 4, 'مشاركة كافة الأطراف المعنية في عملية المراجعة والتحديث، من خلال وسائل مثل: الاستبانات، والاجتماعات، وتقديم المقترحات، وتشكيل لجان المراجعة.', 1, 37),
  ('1.1.3', 'guidance', 5, 'توظيف نتائج عملية المراجعة في التخطيط الاستراتيجي والتشغيلي والتعديل على كافة ممارسات المدرسة وخططها.', 1, 37),
  ('1.1.3', 'reflection', 1, 'ما هي الآلية والإجراءات التي تطبقها المدرسة لمراجعة الرؤية والرسالة والأهداف؟', NULL, 36),
  ('1.1.3', 'reflection', 2, 'ما مدى انتظام عملية المراجعة؟', NULL, 37),
  ('1.1.3', 'reflection', 3, 'من هم الأطراف المشاركون في عملية المراجعة والتحديث؟', NULL, 37),
  ('1.1.3', 'reflection', 4, 'ما مدى توافق التعديلات المقترحة مع التغيرات التربوية والاجتماعية والوطنية؟', NULL, 37),
