  ('1.2.1', 'guidance', 1, 'مدى تقيد المدرسة بتطبيق كافة القوانين واللوائح التنظيمية الصادرة عن وزارة التربية والتعليم والتعليم العالي، بما يضمن انتظام العملية التعليمية والإدارية.', 1, 38),
  ('1.2.1', 'guidance', 2, 'ويشمل ذلك – على سبيل المثال لا الحصر – ما يلي:', 1, 38),
  ('1.2.1', 'guidance', 3, 'القوانين والأنظمة الخاصة بشؤون الطلبة، مثل (القبول والتسجيل، الطاقة الاستيعابية للطلبة).', 2, 38),
  ('1.2.1', 'guidance', 4, 'القوانين والأنظمة الخاصة بشؤون الموظفين مثل (التعيين، موافقات الموظفين، تطابق الوظائف مع موافقات وزارة التربية والتعليم والتعليم العالي، التراخيص المهنية إن وجدت).', 2, 38),
  ('1.2.1', 'guidance', 5, 'السياسة الأكاديمية لتدريس المواد الإلزامية.', 2, 38),
  ('1.2.1', 'guidance', 6, 'الالتزام بالتعاميم والقرارات المستجدة الصادرة من وزارة التربية والتعليم والتعليم العالي خلال العام الدراسي.', 2, 38),
  ('1.2.1', 'guidance', 7, 'مدى امتثال المدرسة لكافة القوانين واللوائح والاشتراطات التنظيمية الصادرة عن الجهات الحكومية ذات العلاقة بعمل المؤسسات التعليمية في الدولة.', 1, 38),
  ('1.2.1', 'guidance', 8, 'ويشمل ذلك – على سبيل المثال لا الحصر – ما يلي:', 1, 38),
  ('1.2.1', 'guidance', 9, 'الاشتراطات الصحية الصادرة عن وزارة الصحة العامة، مثل: معايير الصحة المدرسية، التطعيمات، اشتراطات المقاصف، وإجراءات مكافحة العدوى).', 2, 38),
  ('1.2.1', 'guidance', 10, 'متطلبات الأمن والسلامة والتراخيص بالتنسيق مع وزارة الداخلية والدفاع المدني، وفق الضوابط المعتمدة.', 2, 39),
  ('1.2.1', 'guidance', 11, 'تجديد التراخيص والشهادات الرسمية خلال المدد الزمنية المحددة، ومعالجة الملاحظات الواردة من الجهات الرقابية في الإطار الزمني المعتمد.', 2, 39),
  ('1.2.1', 'reflection', 1, 'ما مدى اطلاع قيادة المدرسة والعاملين فيها على القوانين والأنظمة واللوائح الصادرة عن وزارة التربية والتعليم والتعليم العالي والجهات الرسمية الأخرى؟', NULL, 38),
  ('1.2.1', 'reflection', 2, 'كيف تضمن المدرسة تطبيق هذه الأنظمة واللوائح في كافة جوانب العمل؟', NULL, 38),
  ('1.2.1', 'reflection', 3, 'إلى أي مدى تلتزم المدرسة بتطبيق أنظمة ولوائح وزارة التربية والتعليم والتعليم العالي والجهات الحكومية ذات العلاقة؟', NULL, 38),
  ('1.2.1', 'reflection', 4, 'هل تم رصد أية ملاحظات من الوزارة أو الجهات الحكومية ذات العلاقة تشير إلى وجود قصور في الالتزام؟ وفي حال وجودها، ما الإجراءات التصحيحية التي تم اتخاذها؟', NULL, 38),
