  ('3.1.1', 'guidance', 3, 'أدوات التقييم: الوسائل أو النماذج المحددة التي تُستخدم ضمن طرق التقييم لجمع بيانات دقيقة وموثوقة عن أداء الطلبة.', 1, 112),
  ('3.1.1', 'guidance', 4, 'تنويع أدوات التقييم بين الكمية مثل (درجات الطلاب في الاختبارات المدرسية)، والوصفية مثل (قوائم التحقق، بطاقة الملاحظة، وسلالم التقدير، وملفات الإنجاز) لضمان شمولية التقييم.', 1, 112),
  ('3.1.1', 'guidance', 5, 'تقارير الطلبة (واضحة): تعرض التقارير بيانات الأداء بلغة مفهومة ومنظمة، بما يسهل على المعنيين فهم النتائج وتفسيرها.', 1, 112),
  ('3.1.1', 'guidance', 6, 'تقارير الطلبة (شاملة): تغطي مختلف جوانب أداء الطلبة الأكاديمية والمهارية والسلوكية، وتوفر صورة متكاملة عن تقدمهم، كما توضح التقارير نقاط القوة والنقاط التي تحتاج إلى تحسين، وتقدم توصيات لتحسين الأداء.', 1, 113),
  ('3.1.1', 'reflection', 1, 'إلى أي مدى تضمن سياسة التقييم شمولية كافة جوانب أداء الطلبة؟', NULL, 112),
  ('3.1.1', 'reflection', 2, 'هل يتم مراجعة وتحديث سياسة التقييم بشكلٍ دوري؟ وما المعايير أو الأدلة التي تستند إليها المدرسة في ذلك؟', NULL, 112),
  ('3.1.1', 'reflection', 3, 'إلى أي مدى تتوافق سياسة التقييم وأدواته مع المنهج الدراسي من حيث نواتج التعلم، وأنواع التقييم، ونظام تقدير الدرجات؟', NULL, 112),
  ('3.1.1', 'reflection', 4, 'كيف يتم تعريف الأطراف المعنية بسياسة التقييم، وكيف يتم التأكد من فهمهم لأدوارهم في تطبيقها؟', NULL, 112),
  ('3.1.1', 'reflection', 5, 'ما مدى تنوع أدوات التقييم المستخدمة لتغطية مختلف جوانب أداء الطلبة، وكيف يتم ضمان عدالتها وملاءمتها؟', NULL, 112),
  ('3.1.1', 'reflection', 6, 'ما آلية إعداد وإرسال ومناقشة تقارير أداء الطلبة، وما مدى وضوحها وشمولها ودقتها في عكس مستوى أداء الطلبة؟', NULL, 112),
  ('3.1.2', 'guidance', 1, 'أدوات سياسة القبول، مثل: المقابلات الشخصية، الاختبارات التحريرية، الملاحظات، المقابلة، تقارير الأداء من المدارس السابقة.', 1, 113),
  ('3.1.2', 'guidance', 2, 'الاختبارات التشخيصية: اختبارات تجرى بهدف تحديد مستوى المعرفة والمهارات التي يمتلكها الطلبة في مجالات دراسية محددة، لتشخيص جوانب القوة والتحسين لديهم، بما يُسهم في توجيه عملية التعليم والتعلم وتقديم الدعم المناسب.', 1, 113),
  ('3.1.2', 'guidance', 3, 'إعداد التقييمات بدقة لضمان توافقها التام مع الأهداف التعليمية المحددة والمحتوى الدراسي لكل صف أو مرحلة دراسية.', 1, 113),
  ('3.1.2', 'guidance', 4, 'تنوع أسئلة الاختبارات (مثل: أسئلة اختيار من متعدد، مقالية، أسئلة مهارات التفكير العليا) مع مراعاة العمق المعرفي والتدرج ومهارات التفكير العليا في الأسئلة.', 1, 113),
  ('3.1.2', 'guidance', 5, 'تُقدم التغذية الراجعة للطلبة بعد مختلف أنواع التقييمات، ولا يقتصر تقديمها على الاختبارات أو التطبيقات، بل تشمل كافة المواقف التي يتم فيها جمع الأدلة حول تعلم الطلبة وأدائهم كالمشاريع والأبحاث.', 1, 114),
  ('3.1.2', 'reflection', 1, 'ما هي الإجراءات المتبعة لقبول الطلبة في المدرسة؟', NULL, 113),
  ('3.1.2', 'reflection', 2, 'متى يتم تقديم اختبارات تشخيصية لتحديد مستوى معارف ومهارات الطلبة؟ وفي أي مواد؟ وكيف يتم توظيف نتائجها في تحسين التعليم والتعلم؟', NULL, 113),
  ('3.1.2', 'reflection', 3, 'كيف تضمن المدرسة أن أدوات وأساليب التقييم الداخلي تتسم بالوضوح، وتنسجم مع نواتج التعلم وأهداف المنهج؟', NULL, 113),
  ('3.1.2', 'reflection', 4, 'ما الإجراءات المتبعة لضمان العدالة والموضوعية في تقدير أداء الطلبة عبر أدوات وأساليب التقييم الداخلي؟', NULL, 113),
  ('3.1.2', 'reflection', 5, 'كيف تضمن المدرسة دقة وموثوقية تصحيح الاختبارات الداخلية؟', NULL, 113),
  ('3.1.2', 'reflection', 6, 'ما آليات تقديم التغذية الراجعة للطلبة بعد عمليات التقييم المختلفة، وكيف يتم التأكد من فاعليتها في تحسين التعلم؟', NULL, 113),
  ('3.1.3', 'guidance', 1, 'الاختبارات الخارجية كل اختبار أو تقييم يُجرى تحت إشراف جهات أو هيئات تعليمية خارجية ويشمل المعيارية، التحصيلية، الثانوية، الدولية.', 1, 114),
  ('3.1.3', 'guidance', 2, 'قدرة المدرسة على تحضير الطلبة للاختبارات الخارجية، بما يشمل الجوانب المعرفية، المهارية، والسلوكية.', 1, 114),
  ('3.1.3', 'guidance', 3, 'تطبيق ممارسات تعليمية منهجية خلال الحصص الدراسية في المواد المختلفة ترتكز على تنمية المعارف والمهارات المرتبطة بمعايير المنهج، وليس الاقتصار على التدريب على نماذج الاختبارات.', 1, 114),
  ('3.1.3', 'guidance', 4, 'التدريب والتهيئة للاختبارات من خلال مجموعة من الإجراءات، مثل: مراجعة المناهج، تنمية مهارات استراتيجيات الإجابة وإدارة الوقت، تطوير مهارات الطلبة في التعامل مع أنماط الأسئلة المختلفة.', 1, 114),
  ('3.1.3', 'guidance', 5, 'تقديم الدعم الأكاديمي والنفسي المستمر للطلبة أثناء التحضير للاختبارات لتعزيز ثقتهم بأنفسهم وضمان جاهزيتهم النفسية والتربوية.', 1, 114),
  ('3.1.3', 'guidance', 6, 'استخدام أدوات عملية للتحضير مثل: الاختبارات التجريبية، نماذج الأسئلة السابقة، أوراق العمل أثناء الحصص الدراسية تشتمل على نمط أسئلة الاختبارات، التدريب على الوقت المحدد لكل اختبار.', 1, 115),
  ('3.1.3', 'reflection', 1, 'ما الإجراءات المتبعة لتدريب وتهيئة الطلبة للاختبارات المعيارية/ التحصيلية؟ وكيف يتم تقييم فاعلية هذه الإجراءات؟', NULL, 114),
  ('3.1.3', 'reflection', 2, 'ما الإجراءات المتبعة لتدريب وتهيئة الطلبة-لاختبارات الشهادة الثانوية؟ وكيف يتم التأكد من جاهزيتهم ومدى فاعلية برامج التهيئة المقدمة لهم؟', NULL, 114),
  ('3.1.3', 'reflection', 3, 'كيف تقوم المدرسة بتهيئة الطلبة للاختبارات الدولية لضمان جاهزيتهم، وكيف يتم متابعة أثر هذه البرامج وقياس نتائجها؟', NULL, 114),
  ('3.1.4', 'guidance', 1, 'تحقيق الطلبة باختلاف قدراتهم ومستوياتهم تقدماً في كافة المواد الدراسية عبر فترات زمنية متعاقبة (ثلاث سنوات) من خلال مقارنة نتائج الاختبارات دورياً.', 1, 115),
  ('3.1.4', 'guidance', 2, 'مستويات الأداء المرتفعة: مستويات متقدمة في نواتج التعلّم وفق المنهج المعتمد في المدرسة.', 1, 115),
  ('3.1.4', 'guidance', 3, 'يتم الحكم على مستوى الأداء وفق المنهج المطبق في المدرسة.', 1, 115),
  ('3.1.4', 'reflection', 1, 'كيف يتم التحقق من تقدم مستوى أداء كافة الطلبة في المواد الدراسية المختلفة؟', NULL, 115),
  ('3.1.4', 'reflection', 2, 'إلى أي مدى تتوافق نتائج التقييمات الداخلية مع نتائج التقييمات الخارجية والدولية؟ وكيف يتم التحقق من ذلك؟', NULL, 115),
  ('3.1.4', 'reflection', 3, 'في حال وجود فروق بين نتائج التقييمات الداخلية والخارجية، ما الأسباب المحتملة لذلك؟ وكيف يتم التعامل معها؟', NULL, 115),
  ('3.1.4', 'reflection', 4, 'كيف تستفيد المدرسة من بيانات الأداء عبر السنوات في قياس مدى تحقق نواتج التعلم المستهدفة؟', NULL, 115),
  ('3.1.5', 'guidance', 1, 'الاختبارات المعيارية: تقييمات رسمية مرتبطة بالمنهج المطبق في المدرسة، وتقيس مدى تحقق معاييره ومخرجاته التعليمية، وغالباً تكون على مستوى وطني أو دولي، وهي اختبارات معتمدة من جهات تعليمية رسمية خارج المدرسة..', 1, 115),
  ('3.1.5', 'guidance', 2, 'أمثلة على هذه الاختبارات: الاختبارات المعيارية مثل: (MAP Checkpoint, Cambridge, الاختبارات التحصيلية الوطنية).', 1, 116),
  ('3.1.5', 'guidance', 3, 'يتم تنفيذ الاختبارات المعيارية للمراحل الدراسية المختلفة حسب المنهج المعتمد.', 1, 116),
  ('3.1.5', 'guidance', 4, 'تُحلل نتائج الطلبة وتقارن بمستويات الأداء المرجعية أو المستهدفة المحددة من الجهة المطورة للاختبار.', 1, 116),
  ('3.1.5', 'guidance', 5, 'مستوى الأداء المستهدف: مستوى الأداء المرجعي المحدد من قبل الجهة المطورة للاختبار المعياري.', 1, 116),
  ('3.1.5', 'guidance', 6, 'عدم اقتصار تقديم الاختبارات المعيارية على الطلبة المتميزين والمتفوقين.', 1, 116),
  ('3.1.5', 'guidance', 7, 'يتم تصحيح الاختبارات المعيارية في المراكز والمؤسسات المعتمدة.', 1, 116),
  ('3.1.5', 'guidance', 8, 'مقارنة النتائج عبر فترات زمنية متعاقبة (3 سنوات).', 1, 116),
  ('3.1.5', 'reflection', 1, 'ما هي معايير المدرسة في اختيار الاختبارات المعيارية؟', NULL, 115),
  ('3.1.5', 'reflection', 2, 'ما هي معايير تحديد الصفوف/ المراحل التعليمية المستهدفة من الطلبة لتقديم الاختبارات المعيارية؟', NULL, 115),
  ('3.1.5', 'reflection', 3, 'كيف تقيم المدرسة مستوى أداء الطلبة في الاختبارات المعيارية؟ وما مدى وضوح واستمرارية التقدم في الأداء عبر الفترات الزمنية المتعاقبة؟', NULL, 115),
  ('3.1.6', 'guidance', 1, 'اختبارات الشهادة الثانوية: اختبارات رسمية تُجرى في المرحلة الثانوية، وتهدف إلى تقييم مدى تحقق الأهداف التعليمية والمعرفية للطلبة وفق المنهج الدراسي المعتمد.', 1, 116),
  ('3.1.6', 'guidance', 2, 'أمثلة على اختبارات الشهادة الثانوية: امتحانات الثانوية العامة التي تجريها وزارة التربية والتعليم والتعليم العالي، اختبارات (IGCSE، A level، البكالوريا الدولية، CBSE، AP).', 1, 116),
  ('3.1.6', 'guidance', 3, 'متابعة وتحليل نتائج اختبارات الشهادة الثانوية على مدى السنوات لتحديد مدى تحسن الأداء الأكاديمي للطلبة بمرور الوقت (3سنوات).', 1, 117),
  ('3.1.6', 'guidance', 4, 'مقارنة نتائج الطلبة بنتائج المجموعات المرجعية الوطنية أو الدولية ذات الصلة، مما يعكس جودة التعليم المقدم.', 1, 117),
  ('3.1.6', 'reflection', 1, 'هل يتم تطبيق اختبارات الشهادة الثانوية على كافة الطلبة في المرحلة المستهدفة دون استثناء؟', NULL, 116),
  ('3.1.6', 'reflection', 2, 'ما الأسباب التي دعت إلى عدم تطبيق هذه الاختبارات على بعض مجموعات الطلبة؟ ما الإجراءات التي اتخذتها المدرسة لتأهيل هذه المجموعات لأداء الاختبارات؟', NULL, 116),
  ('3.1.6', 'reflection', 3, 'ما هي التحديات التي تواجه المدرسة في تطبيق هذه الاختبارات؟ وكيف يتم التعامل معها؟', NULL, 117),
  ('3.1.6', 'reflection', 4, 'كيف تقيم المدرسة مستوى أداء الطلبة في هذه الاختبارات، وما مدى وضوح واستمرارية التقدم في الأداء عبر الفترات الزمنية المتعاقبة؟', NULL, 117),
  ('3.1.7', 'guidance', 1, 'تشمل الاختبارات الدولية اختبارات بيزا (PISA) وتيمز (TIMSS) وبيرلز (PIRLS).', 1, 117),
  ('3.1.7', 'guidance', 2, 'تُفسَّر نتائج الطلبة ويتم تقييمها وفق المستويات المرجعية الدولية المعتمدة من الجهة المنظمة للاختبار، والتي تعتمد على نطاقات درجات معيارية تُصنّف الأداء إلى مستويات متدرجة، بما يعكس مستوى إتقان الطلبة للمهارات والمعارف المستهدفة.', 1, 117),
  ('3.1.7', 'reflection', 1, 'ما هو مستوى أداء الطلبة في الاختبارات الدولية مقارنة بالمستوى المحلي / الدولي؟', NULL, 117),
  ('3.1.7', 'reflection', 2, 'كيف يتم الاستفادة من نتائج تلك الاختبارات؟ وما أثر ذلك على تعلم الطلبة؟', NULL, 117),
  ('3.1.8', 'guidance', 1, 'النمو المعرفي: تقدم الأطفال في اكتساب المهارات اللغوية، والمفاهيم الرياضية والعلمية، ومهارات التفكير وحل المشكلات.', 1, 117),
  ('3.1.8', 'guidance', 2, 'النمو الاجتماعي: تقدم الأطفال في مهارات التفاعل الإيجابي مع الأقران والبالغين، والتعاون والعمل ضمن المجموعة، والاستقلالية الاجتماعية بما يتناسب مع خصائصهم العمرية.', 1, 117),
  ('3.1.8', 'guidance', 3, 'النمو الانفعالي: تقدم الأطفال في مهارات التعبير عن مشاعرهم وفهم مشاعر الآخرين، وتنظيم الانفعالات والتعامل مع المواقف الصعبة والتغيرات.', 1, 118),
  ('3.1.8', 'guidance', 4, 'النمو الجسدي والمهارات الحركية: تقدم الأطفال في استخدام العضلات الكبيرة والعضلات الدقيقة.', 1, 118),
  ('3.1.8', 'guidance', 5, 'أدوات تقييم المهارات المختلفة، مثل: الملاحظة المباشرة، ملف الإنجاز، التقييمات المتنوعة، المقاييس النمائية، أوراق العمل.', 1, 118),
  ('3.1.8', 'reflection', 1, 'كيف يتم التحقق من مستوى تقدم الأطفال في مجالات النمو المختلفة (المعرفي، الاجتماعي، الانفعالي، والجسدي)؟', NULL, 117),
  ('3.1.8', 'reflection', 2, 'إلى أي مدى يُظهر الأطفال استمرارية في التقدم في مهاراتهم بما يتناسب مع أهداف المنهج وخصائصهم العمرية؟', NULL, 117),
  ('3.1.8', 'reflection', 3, 'ما الأدوات والأساليب المستخدمة في متابعة وتوثيق تقدم الأطفال وتطور مهاراتهم؟', NULL, 118),
  ('3.1.8', 'reflection', 4, 'كيف يتم التأكد من أن مستوى أداء الأطفال يتوافق مع الأهداف التعليمية للمرحلة العمرية؟', NULL, 118),
  ('3.1.8', 'reflection', 5, 'ما مدى دقة البيانات المستخلصة من متابعة تقدم الأطفال في عكس واقع نموهم وتطورهم؟', NULL, 118),
  ('3.1.8', 'reflection', 6, 'كيف يتم رصد الفجوات أو التفاوت في مستويات تقدم الأطفال عبر مجالات النمو المختلفة؟', NULL, 118),
  ('3.1.9', 'guidance', 1, 'التقييمات المختلفة، مثل: الداخلية، الاختبارات المعيارية، اختبارات الشهادة الثانوية، والاختبارات الدولية.', 1, 118),
  ('3.1.9', 'guidance', 2, 'يشمل التحليل قياس تقدم أداء الطلبة في المعارف والمهارات من خلال تنوع أدوات التقييم.', 1, 118),
  ('3.1.9', 'guidance', 3, 'تحليل نتائج الطلبة في كافة المواد الدراسية على المستوى الفردي، ومستوى الصفوف والمراحل الدراسية، بشكلٍ فصلي وسنوي، مع إجراء مقارنات عبر فترات زمنية متعاقبة للتحقق من مدى التقدم.', 1, 118),
  ('3.1.9', 'guidance', 4, 'الاستفادة من نتائج التحليل في اتخاذ القرارات، مثل: التعديل على الخطط السنوية والفصلية، خطط الدروس، المصادر التعليمية، برامج وخطط الدعم الفردية، الأنشطة التعليمية.', 1, 118),
  ('3.1.9', 'reflection', 1, 'هل يتم تحليل نتائج تقييمات الطلبة بشكلٍ دوري ومنهجي على مستوى المواد والصفوف والمراحل الدراسية؟', NULL, 118),
  ('3.1.9', 'reflection', 2, 'ما الأدوات والطرق المستخدمة في تحليل بيانات نتائج تقييمات الطلبة؟', NULL, 118),
  ('3.1.9', 'reflection', 3, 'كيف تُستخدم نتائج التحليل لتحديد الاتجاهات العامة في أداء الطلبة، ونقاط القوة والتحسين؟', NULL, 118),
  ('3.1.9', 'reflection', 4, 'كيف تُوظف نتائج تحليل الأداء في تحسين جودة التعليم والتعلم؟', NULL, 118),
  ('3.2.1', 'guidance', 1, 'الطلبة الموهوبون: هم الأفراد الذين يظهرون قدرات فائقة أو أداءً متفوقاً في مجال أو أكثر مقارنة بأقرانهم، ويحتاجون إلى بيئة تعليمية مخصصة تدعم تنمية مهاراتهم وقدراتهم.', 1, 120),
  ('3.2.1', 'guidance', 2, 'أنواع المواهب، مثل: الموهبة الفنية، الحركية، الأكاديمية، التقنية، الاجتماعية.', 1, 120),
  ('3.2.1', 'guidance', 3, 'وجود إجراءات محددة وواضحة لتحديد واكتشاف المواهب.', 1, 120),
  ('3.2.1', 'guidance', 4, 'الإجراءات المحددة: خطوات منظمة ومكتوبة لتحديد الطلبة الموهوبين، وفق تسلسل إجرائي ثابت، باستخدام أدوات تقييم متنوعة، مثل: الملاحظات، والاختبارات، والمسابقات، ومقاييس المواهب.', 1, 120),
  ('3.2.1', 'guidance', 5, 'إشراك المعلمين وأولياء الأمور والمتخصصين في عملية الترشيح والتحديد.', 1, 120),
  ('3.2.1', 'guidance', 6, 'تقديم برامج إثرائية متنوعة تتناسب مع المواهب المختلفة، (مثل: ورش فنية، عروض موسيقية، فعاليات ثقافية، أنشطة رياضية، مشاريع بحثية).', 1, 120),
  ('3.2.1', 'guidance', 7, 'توفير بيئة تعليمية وموارد محفزة تشجع الطلبة على استثمار مواهبهم وتنمية قدراتهم.', 1, 120),
  ('3.2.1', 'reflection', 1, 'ما هي الآلية والإجراءات المتبعة لتحديد الطلبة الموهوبين في المدرسة؟ وما مدى فعالية هذه الإجراءات؟', NULL, 120),
  ('3.2.1', 'reflection', 2, 'ما البرامج والأنشطة المقدمة لتنمية مهارات ومواهب الطلبة الموهوبين؟ وإلى أي مدى تستجيب لاحتياجاتهم؟', NULL, 120),
  ('3.2.1', 'reflection', 3, 'كيف يتم متابعة وتقييم خطط وبرامج رعاية الموهوبين؟ وما الأدلة على فاعليتها؟', NULL, 120),
  ('3.2.1', 'reflection', 4, 'ما أثر برامج رعاية الموهوبين على تعزيز مهارات وقدرات الطلبة وتحقيقهم للإنجازات المختلفة؟', NULL, 120),
  ('3.2.2', 'guidance', 1, 'الطلبة ذوو الأداء الأكاديمي المنخفض: هم الطلبة الذين لم يحققوا مستويات النجاح أو نواتج التعلم المتوقعة في مادة دراسية واحدة أو في عدة مواد، مقارنة بالمستوى الأكاديمي المستهدف.', 1, 121),
  ('3.2.2', 'guidance', 2, 'تحديد الطلبة ذوي الأداء المنخفض بدقة بناء على نتائج التقييمات والاختبارات المختلفة.', 1, 121),
  ('3.2.2', 'guidance', 3, 'الخطط ذات جودة، وشاملة لكافة العناصر الأساسية، وواضحة ومحددة، مثل: الأهداف، ومؤشرات أداء قابلة للقياس، والمدى الزمني.', 1, 121),
  ('3.2.2', 'guidance', 4, 'إعداد خطط فردية أو جماعية تستهدف طلبة الأداء المنخفض.', 1, 121),
  ('3.2.2', 'reflection', 1, 'كيف يتم تحديد الطلبة ذوي الأداء الأكاديمي المنخفض؟', NULL, 121),
  ('3.2.2', 'reflection', 2, 'ما الخطط والبرامج المقدمة لدعم هذه الفئة من الطلبة؟', NULL, 121),
  ('3.2.2', 'reflection', 3, 'ما مدى فعالية تنفيذ الخطط لرعاية هذه الفئة من الطلبة؟ وما التعديلات التي يتم إجراؤها بناءً على نتائج التقييم؟', NULL, 121),
  ('3.2.2', 'reflection', 4, 'كيف يتم متابعة تقدم أداء الطلبة ذوي الأداء الأكاديمي المنخفض؟', NULL, 121),
  ('3.2.2', 'reflection', 5, 'ما أثر تطبيق الخطط الداعمة على تحسين مستوى التحصيل الأكاديمي للطلبة؟', NULL, 121),
  ('3.2.3', 'guidance', 1, 'ذوي الإعاقة: هم كل شخص مصاب بعجز، كلي أو جزئي، أو دائم في أي من حواسه، أو قدراته الجسمية، أو النفسية، أو العقلية إلى المدى الذي يحد من إمكانيته للتعلم أو التأهيل.', 1, 121),
  ('3.2.3', 'guidance', 2, 'استخدام طرق وأدوات متنوعة لتحديد الطلبة ذوي الإعاقة، مثل: التقارير الطبية، والملاحظة، والاختبارات التخصصية.', 1, 121),
  ('3.2.3', 'guidance', 3, 'يُجرى التقييم لتحديد نوع وشدة الإعاقة من خلال مختصين من الجهات المختصة بالدولة.', 1, 121),
  ('3.2.3', 'guidance', 4, 'إشراك المعلمين، وأولياء الأمور، والكوادر المختصة في عملية التحديد والإحالة.', 1, 122),
  ('3.2.3', 'guidance', 5, 'توفر تقارير تشخيصية رسمية ومحدَّثة للطلبة ذوي الإعاقة وصعوبات التعلم، صادرة عن جهات مختصة ومعتمدة في الدولة، ومرفقة ببيان التوصيات التربوية ذات الصلة.', 1, 122),
  ('3.2.3', 'guidance', 6, 'الموارد البشرية المؤهلة: اختصاصيين مؤهلين في اختصاصات، مثل: العلاج الطبيعي، والعلاج الوظائفي، والنطق واللغة، والتربية الخاصة.', 1, 122),
  ('3.2.3', 'guidance', 7, 'توفير الأجهزة والوسائل التخصصية التعليمية والتكنولوجية لتلبية احتياجات الطلبة المختلفة.', 1, 122),
  ('3.2.3', 'guidance', 8, 'توفر سجل منظم لحالات الطلبة المشخصين يتضمن نتائج التقييم وقرارات الإحالة والإجراءات المتخذة.', 1, 122),
  ('3.2.3', 'guidance', 9, 'الالتزام بمبادئ السرية والخصوصية في التعامل مع بيانات الطلبة المشخصين وملفاتهم.', 1, 122),
  ('3.2.3', 'reflection', 1, 'كيف يتم تحديد نوع وشدة الإعاقة لدى الطلبة؟', NULL, 121),
  ('3.2.3', 'reflection', 2, 'كيف يتم إعداد الخطط التعليمية الفردية للطلبة ذوي الإعاقة؟ وما الأسس التي تُبنى عليها؟', NULL, 121),
  ('3.2.3', 'reflection', 3, 'إلى أي مدى تراعي الخطط التعليمية الفردية نوع الإعاقة وشدتها واحتياجات كل طالب؟', NULL, 121),
  ('3.2.3', 'reflection', 4, 'ما الإجراءات المتبعة لضمان دمج الطلبة ذوي الإعاقة في الأنشطة التعليمية والاجتماعية داخل المدرسة؟', NULL, 121),
  ('3.2.3', 'reflection', 5, 'كيف يتم تقييم فعالية خطط الدعم المقدمة للطلبة ذوي الإعاقة؟', NULL, 121),
  ('3.2.3', 'reflection', 6, 'كيف تُشرك المدرسة أولياء الأمور والجهات المختصة في وضع وتنفيذ خطط الدعم والرعاية للطلبة ذوي الإعاقة؟', NULL, 122),
  ('3.2.3', 'reflection', 7, 'كيف يتم متابعة تقدم الطلبة ذوي الإعاقة في المدرسة؟ وما الأدوات المستخدمة في ذلك؟', NULL, 122),
  ('3.2.4', 'guidance', 1, 'أدوات التقييم: هي أدوات معيارية ومقننة، مثل: الملاحظة، والاختبارات، ومقاييس سلوكية أو معرفية.', 1, 122),
  ('3.2.4', 'guidance', 2, 'صعوبات التعلم: تعني اضطراب يعوق عملية التعلم الطبيعية، مثل: صعوبات الانتباه والتركيز، أو القراءة، أو الكتابة، أو الحساب.', 1, 122),
  ('3.2.4', 'guidance', 3, 'أنواع الدعم، مثل: التعلم المتمايز، توفير المصادر والوسائل التعليمية، دمج التكنولوجيا.', 1, 123),
  ('3.2.4', 'guidance', 4, 'الأدوات التعليمية المخصصة، مثل: الأدوات التقنية، والبصرية والحسية.', 1, 123),
  ('3.2.4', 'guidance', 5, 'توفر سجل منظم لحالات الطلبة المشخصين يتضمن نتائج التقييم وتطورهم.', 1, 123),
  ('3.2.4', 'reflection', 1, 'كيف يتم تحديد الطلبة ذوي صعوبات التعلم؟', NULL, 122),
  ('3.2.4', 'reflection', 2, 'كيف يتم إعداد الخطط التعليمية الفردية للطلبة ذوي صعوبات التعلم؟ وكيف يتم تقديم الدعم لهذه الفئة من الطلبة؟', NULL, 122),
  ('3.2.4', 'reflection', 3, 'كيف يتم متابعة أداء الطلبة ذوي صعوبات التعلم؟ وما الأدوات المستخدمة في ذلك؟', NULL, 123),
  ('3.2.4', 'reflection', 4, 'كيف يتم تقييم فعالية الدعم التعليمي المقدم للطلبة؟ وما الأدلة التي تُظهر تحسن أدائهم الأكاديمي؟', NULL, 123),
  ('3.2.4', 'reflection', 5, 'كيف يتم تعديل الخطط التعليمية الفردية بناءً على نتائج المتابعة والتقييم لضمان تحسين نواتج التعلم؟', NULL, 123),
  ('3.2.5', 'guidance', 1, 'المهارات اللغوية: هي القدرات الأساسية التي تمكّن الفرد من استخدام اللغة بفعالية في التواصل، وتشمل: الاستماع، والتحدث، والقراءة، والكتابة.', 1, 123),
  ('3.2.5', 'guidance', 2, 'تُستخدم أساليب وأدوات كمية ونوعية بشكلٍ تكاملي لتقييم المهارات اللغوية، مثل: الاختبارات المقننة، والتقييمات الصفية، والملاحظات المنظمة، وتحليل أعمال الطلبة.', 1, 123),
  ('3.2.5', 'guidance', 3, 'المشاركة في المسابقات، والبرامج، والأنشطة لدعم تحصيل اللغة، مثل: الخطابة، الإلقاء، المناظرات.', 1, 123),
  ('3.2.5', 'reflection', 1, 'كيف تُحدد المدرسة احتياجات الطلبة في المهارات اللغوية المختلفة (الاستماع، التحدث، القراءة، الكتابة)؟', NULL, 123),
  ('3.2.5', 'reflection', 2, 'ما أنواع الخطط والبرامج التي تُنفذ لدعم تنمية المهارات اللغوية لدى الطلبة؟', NULL, 123),
  ('3.2.5', 'reflection', 3, 'كيف يُدمج دعم تنمية المهارات اللغوية في مختلف المواد الدراسية لتعزيز تحقيق أهداف المنهج؟', NULL, 123),
  ('3.2.5', 'reflection', 4, 'ما مدى كفاءة المعلمين في تنفيذ استراتيجيات تعليم وتعلم تدعم تنمية المهارات اللغوية؟', NULL, 123),
  ('3.2.5', 'reflection', 5, 'كيف تُقيّم المدرسة مدى تقدم المهارات اللغوية لدى الطلبة؟', NULL, 123),
  ('3.2.6', 'guidance', 1, 'الإرشاد الأكاديمي: هو عملية منظمة تهدف إلى توجيه الطلبة لاتخاذ قرارات دراسية مناسبة وفقاً لقدراتهم واهتماماتهم.', 1, 124),
  ('3.2.6', 'guidance', 2, 'الإرشاد المهني: هو عملية تساعد الطلبة على استكشاف ميولهم وفرصهم المستقبلية لاتخاذ قرارات واعية بشأن مساراتهم المهنية.', 1, 124),
  ('3.2.6', 'guidance', 3, 'تشمل برامج الإرشاد الأكاديمي والمهني:', 1, 124),
  ('3.2.6', 'guidance', 4, 'تقديم الدعم للطلبة في اختيار الجامعات والتخصصات، مع التوجيه حول متطلبات التقديم والقبول.', 2, 124),
  ('3.2.6', 'guidance', 5, 'إشراك أولياء الأمور في عملية الإرشاد الأكاديمي والمهني.', 2, 124),
  ('3.2.6', 'guidance', 6, 'تقديم جلسات إرشادية للطلبة، سواء بشكلٍ فردي أو جماعي.', 2, 124),
  ('3.2.6', 'guidance', 7, 'التنسيق مع الجهات الخارجية لتقديم الدعم، مثل: التعاون مع الجامعات، والتنسيق مع مؤسسات سوق العمل، والاستفادة من المختصين في مجالات مهنية مختلفة.', 2, 124),
  ('3.2.6', 'reflection', 1, 'ما هي خدمات الإرشاد الأكاديمي والمهني التي تقدمها المدرسة للطلبة؟', NULL, 124),
  ('3.2.6', 'reflection', 2, 'هل توفر المدرسة اختيارات من المواد الدراسية بما يلبي احتياجات الطلبة المختلفة؟ كيف تم تحديد هذه المواد؟', NULL, 124),
  ('3.2.6', 'reflection', 3, 'ما مدى انتظام تقديم جلسات الإرشاد الأكاديمي والمهني، وهل تشمل كافة الطلبة؟', NULL, 124),
  ('3.2.6', 'reflection', 4, 'ما مدى تأهيل وتخصص الكوادر المسؤولة عن تقديم خدمات الإرشاد الأكاديمي والمهني في المدرسة؟', NULL, 124),
  ('3.2.6', 'reflection', 5, 'كيف يتم قياس أثر برامج الإرشاد الأكاديمي والمهني على وعي الطلبة واتخاذهم لقرارات تعليمية أو مهنية مناسبة؟', NULL, 124),
  ('3.2.6', 'reflection', 6, 'كيف يتم قياس رضا الطلبة وأولياء الأمور عن خدمات الإرشاد الأكاديمي والمهني المقدمة؟', NULL, 124),
  ('3.2.6', 'reflection', 7, 'هل يتم إشراك أولياء الأمور والمعلمين في عملية الإرشاد الأكاديمي والمهني؟ وكيف؟', NULL, 124),
  ('3.2.7', 'guidance', 1, 'الإرشاد النفسي: يركز على دعم الصحة النفسية والعاطفية للطلبة، ويساعدهم في التعامل مع المشكلات النفسية، مثل: القلق، والاكتئاب، والتوتر، وصعوبات التكيف مع الضغوط النفسية.', 1, 124),
  ('3.2.7', 'guidance', 2, 'دعم احتياجات الطلبة الفردية من خلال معالجة الصدمات النفسية أو الأزمات الشخصية التي قد تؤثر على الأداء الأكاديمي والعلاقات الشخصية للطلبة، مثل: فهم أنفسهم، وتحسين احترام الذات، وتعزيز الثقة بالنفس.', 1, 125),
  ('3.2.7', 'guidance', 3, 'بناء شراكات وتنسيق مع أولياء الأمور والجهات المختصة (مثل المراكز النفسية والصحية) بهدف تقديم دعم نفسي متكامل للطلبة، يشمل إحالة الطلبة عند الحاجة، وتنفيذ برامج أو تدخلات مشتركة.', 1, 125),
  ('3.2.7', 'reflection', 1, 'ما الإجراءات المتبعة في المدرسة لتحديد وتشخيص وإحالة الطلبة الذين يحتاجون إلى خدمات الإرشاد النفسي؟', NULL, 124),
  ('3.2.7', 'reflection', 2, 'ما الخطط والبرامج والأنشطة المقدمة لدعم الصحة النفسية للطلبة؟', NULL, 125),
  ('3.2.7', 'reflection', 3, 'كيف يتم تقييم فعالية خدمات الدعم النفسي المقدمة للطلبة؟ وما الأدلة على تحسن حالاتهم أو استفادتهم من التدخلات؟', NULL, 125),
  ('3.2.7', 'reflection', 4, 'ماهي الجهات التي تتعاون معها المدرسة لتوفير الدعم المناسب؟ كيف يتم التعاون معها؟', NULL, 125),
  ('3.2.7', 'reflection', 5, 'ما هو دور أولياء الأمور في تقديم الدعم لأبنائهم؟', NULL, 125),
  ('3.2.7', 'reflection', 6, 'ما البرامج والأنشطة التوعوية والوقائية المقدمة لتعزيز الصحة النفسية لدى الطلبة؟ وما مدى مشاركتهم فيها؟', NULL, 125),
  ('3.2.8', 'guidance', 1, 'الإرشاد الاجتماعي: يركز على تطوير مهارات التواصل الاجتماعي، وبناء العلاقات، والتكيف مع البيئة الاجتماعية المدرسية، ويهدف إلى مساعدة الطلبة في التفاعل بشكلٍ إيجابي مع الآخرين، سواء مع زملائهم، أو المعلمين، أو أفراد الأسرة، وحل المشكلات الاجتماعية مثل التنمر، العزلة، أو التكيف والاندماج في المجتمع المدرسي.', 1, 125),
  ('3.2.8', 'guidance', 2, 'دعم احتياجات الطلبة الفردية من خلال تعليمهم مهارات اجتماعية مثل: التعاون، التفاعل، بناء صداقات، احترام التنوع.', 1, 125),
  ('3.2.8', 'guidance', 3, 'تضمين الخطط برامج علاجية مبنية على نتائج التشخيص للحالات الفردية، وبرامج وقائية توعوية موجهة لكافة الطلبة، تشمل أنشطة جماعية منظمة (ورش عمل، تدريبات اجتماعية، مناقشات تربوية) تُعنى بتنمية القيم الاجتماعية وتعزيز الاحترام المتبادل، ومعالجة التحديات الاجتماعية المؤثرة في التكيف والمشاركة المدرسية.', 1, 126),
  ('3.2.8', 'reflection', 1, 'كيف يتم حصر وتشخيص الحالات التي بحاجة إلى خدمات الدعم والإرشاد الاجتماعي؟', NULL, 125),
  ('3.2.8', 'reflection', 2, 'ما الإجراءات التي تتبعها المدرسة لدعم تلك الفئة من الطلبة؟', NULL, 125),
  ('3.2.8', 'reflection', 3, 'كيف يتم التأكد من فعالية تلك الإجراءات؟', NULL, 125),
  ('3.2.8', 'reflection', 4, 'ما أنواع الورش أو الحملات التي تم تنفيذها خلال العام؟', NULL, 125),
  ('3.2.8', 'reflection', 5, 'كيف يتم تحديد موضوعات التوعية (بناءً على احتياجات الطلبة أم بشكلٍ عام)؟', NULL, 125),
  ('3.2.8', 'reflection', 6, 'ما هو دور أولياء الأمور في تقديم الدعم لأبنائهم؟', NULL, 126),
  ('3.2.8', 'reflection', 7, 'ما الجهات الخارجية التي تتعاون معها المدرسة؟ وما طبيعة هذا التعاون؟ (تحويل حالات، استشارات، برامج مشتركة...)؟ وكيف يتم تقييم فاعلية هذا التعاون؟', NULL, 126),
  ('3.2.8', 'reflection', 8, 'كيف يتم متابعة حالات تلك الفئة من الطلبة؟ ما أثر ذلك على تحسن الحالات؟', NULL, 126),
  ('4.1.1', 'guidance', 1, 'شمولية سياسة السلوك للعناصر الأساسية التي تعزز السلوك الإيجابي، مثل: القواعد السلوكية الواجب اتباعها داخل الصف وخارجه، والسلوك المرفوض مع التدرج في الجزاءات المترتبة على كل سلوك، مناهضة التنمر، احترام التنوع، الحضور والغياب، درجات المخالفات السلوكية.', 1, 151),
  ('4.1.1', 'guidance', 2, 'توفر متخصصين مؤهلين لإدارة سلوك الطلبة وتحديد أدوارهم في معالجة المشاكل السلوكية، مثل: الاخصائي النفسي أو الاجتماعي.', 1, 151),
  ('4.1.1', 'guidance', 3, 'مشاركة السياسة بطرق متنوعة مع الأطراف المعنية، مثل: تضمينها في دليل الطالب/ الموظف / ولي الأمر، نشرها على صفحة المدرسة الإلكترونية، الاجتماعات، عرض القواعد السلوكية في مرافق المدرسة وصفوفها.', 1, 151),
  ('4.1.1', 'guidance', 4, 'متابعة وتحليل سلوك الطلبة: جمع بيانات منتظمة عن السلوكيات داخل المدرسة، وتحليلها لتحديد الاتجاهات وتقييم تأثير البرامج والأنشطة السلوكية، بما يدعم اتخاذ القرارات لتحسين بيئة التعلم وضمان سلامة الطلبة.', 1, 151),
  ('4.1.1', 'guidance', 5, 'تتضمن سياسة حماية الطلبة /الأطفال جوانب متعددة، مثل: السلامة الجسدية، الصحة النفسية، مكافحة التنمر، حماية الخصوصية، وغيرها.', 1, 152),
  ('4.1.1', 'reflection', 1, 'ما هي طرق نشر السياسة ومشاركتها مع الأطراف المعنية؟', NULL, 151),
  ('4.1.1', 'reflection', 2, 'إلى أي مدى يلتزم الطلبة بالقوانين المدرسية داخل الصفوف وفي المرافق المختلفة؟ وما الأدلة التي تثبت ذلك؟', NULL, 151),
  ('4.1.1', 'reflection', 3, 'ما مدى اتساق تطبيق قواعد السلوك بين المعلمين؟', NULL, 151),
  ('4.1.1', 'reflection', 4, 'كيف يتم حصر ومتابعة المخالفات السلوكية؟ كيف تضمن المدرسة علاجها وعدم التكرار؟ وهل الإجراءات المتخذة تربوية أم عقابية فقط؟', NULL, 151),
  ('4.1.1', 'reflection', 5, 'ما هي الأدوات المستخدمة لتحليل سلوك الطلبة؟', NULL, 151),
  ('4.1.1', 'reflection', 6, 'ما نسبة المخالفات السلوكية؟ وهل تُظهر البيانات تحسناً بمرور الوقت؟', NULL, 151),
  ('4.1.1', 'reflection', 7, 'ما البرامج والأنشطة التي تطبقها المدرسة لتعزيز السلوك الإيجابي؟', NULL, 151),
  ('4.1.1', 'reflection', 8, 'إلى أي مدى يعرف الموظفون أدوارهم ومسؤولياتهم في تطبيق سياسة حماية الطفل؟', NULL, 151),
  ('4.1.1', 'reflection', 9, 'ما مستوى تدريب العاملين على التعرف على حالات الإساءة أو الإهمال وآليات التعامل معها؟', NULL, 151),
  ('4.1.1', 'reflection', 10, 'إلى أي مدى يشعر الطلبة بالأمان داخل المدرسة؟ وما الأدلة على ذلك؟', NULL, 152),
  ('4.1.1', 'reflection', 11, 'كيف يتم توعية الطلبة بحقوقهم وكيفية طلب المساعدة؟', NULL, 152),
  ('4.1.1', 'reflection', 12, 'ما دور أولياء الأمور في دعم سياسة حماية الطفل؟', NULL, 152),
  ('4.1.2', 'guidance', 1, 'إظهار القدوة الحسنة من خلال ممارسات، مثل: الالتزام بالمظهر اللائق والمحتشم، واستخدام لغة تواصل إيجابية، والتعامل باحترام مع الطلبة، واستخدام أساليب تربوية مناسبة في توجيه وتقويم السلوك غير المرغوب.', 1, 152),
  ('4.1.2', 'guidance', 2, 'احترام الثقافات المتنوعة: هو التزام تربوي يقوم على تقبّل وتقدير اختلاف الخلفيات الثقافية للطلبة، والتعامل معها بعدالة وإيجابية.', 1, 152),
  ('4.1.2', 'reflection', 1, 'إلى أي مدى يُظهر الموظفون سلوكاً مهنياً إيجابياً يُحتذى به داخل الصفوف وخارجها؟ وما الأدلة على ذلك؟', NULL, 152),
  ('4.1.2', 'reflection', 2, 'إلى أي مدى يلتزم الموظفون بالمظهر اللائق والمحتشم بما يتوافق مع سياسات المدرسة وقيم المجتمع؟', NULL, 152),
  ('4.1.2', 'reflection', 3, 'ما أثر سلوك الموظفين كنماذج قدوة على سلوك الطلبة وانضباطهم؟', NULL, 152),
  ('4.1.2', 'reflection', 4, 'إلى أي مدى تعكس ممارسات المدرسة احترام التنوع الثقافي بين الطلبة والموظفين؟', NULL, 152),
  ('4.1.2', 'reflection', 5, 'ما طبيعة العلاقات بين الطلبة والموظفين وبين الطلبة أنفسهم؟ وما الأدلة على إيجابية العلاقة؟', NULL, 152),
  ('4.1.3', 'guidance', 1, 'انضباط الطلبة: التزامهم بالأنظمة والقوانين المتعلقة بالحضور والمواظبة، ويشمل الالتزام بالمواعيد المحددة للحضور إلى المدرسة وبدء الحصص الدراسية، والانتظام خلال اليوم الدراسي دون تأخير أو غياب غير مبرر.', 1, 152),
  ('4.1.3', 'guidance', 2, 'متابعة سجلات الغياب والتأخير، وتحليل الأسباب، ثم اتخاذ إجراءات وقائية وعلاجية لضمان رفع مستوى الحضور والانضباط.', 1, 153),
  ('4.1.3', 'reflection', 1, 'كيف يتم متابعة التزام الطلبة بالحضور للمدرسة؟', NULL, 152),
  ('4.1.3', 'reflection', 2, 'كيف يتم متابعة تأخر الطلبة الصباحي أو خلال اليوم الدراسي؟', NULL, 152),
  ('4.1.3', 'reflection', 3, 'ما الإجراءات المتبعة في حال تكرار الغياب (بدون عذر) أو التأخير؟', NULL, 152),
  ('4.1.3', 'reflection', 4, 'ما مدى فعالية تلك الإجراءات على التزام الطلبة بالحضور وعدم التأخير؟', NULL, 153),
  ('4.1.4', 'guidance', 1, 'المهارات القيادية للطلبة: هي القدرات التي تمكّنهم من التأثير الإيجابي في الآخرين، والعمل ضمن فريق، واتخاذ المبادرة، والتخطيط واتخاذ القرار في المواقف المختلفة.', 1, 153),
  ('4.1.4', 'guidance', 2, 'يتم تعزيز المهارات القيادية لدى الطلبة من خلال، على سبيل المثال: (المشاركة في صنع القرار، إسناد أدوار ومسؤوليات قيادية كقيادة الفرق، تنظيم الفعاليات، الإشراف على الطلبة، تعزيز العمل التطوعي وخدمة المجتمع).', 1, 153),
  ('4.1.4', 'guidance', 3, 'الاحتفاء بإنجازات الطلبة: إبراز وتقدير إنجازاتهم الأكاديمية وغير الأكاديمية والسلوكية، من خلال أساليب متنوعة مادية ومعنوية.', 1, 153),
  ('4.1.4', 'reflection', 1, 'ما هي البرامج والأنشطة المقدمة لتنمية شخصية الطلبة ومهاراتهم القيادية؟', NULL, 153),
  ('4.1.4', 'reflection', 2, 'إلى أي مدى يشارك الطلبة بفعالية في هذه البرامج، وهل تشمل فرصاً حقيقية للقيادة (اتخاذ قرار، تنظيم، مبادرة)؟', NULL, 153),
  ('4.1.4', 'reflection', 3, 'ما أثر تلك البرامج على شخصيات ومهارات الطلبة؟', NULL, 153),
  ('4.1.4', 'reflection', 4, 'هل تتاح فرص القيادة لكافة فئات الطلبة بشكلٍ عادل؟ وما الأدلة على شمولية المشاركة؟', NULL, 153),
  ('4.1.4', 'reflection', 5, 'ما أبرز إنجازات الطلبة (الأكاديمية وغير الأكاديمية)، وما مدى تنوعها؟', NULL, 153),
  ('4.1.4', 'reflection', 6, 'إلى أي مدى تعتمد المدرسة آليات واضحة ومنتظمة للاحتفاء بإنجازات الطلبة في الجوانب الأكاديمية وغير الأكاديمية؟', NULL, 153),
  ('4.1.4', 'reflection', 7, 'ما مدى تنوع أساليب التحفيز والتكريم؟ وكيف تسهم في تعزيز دافعية الطلبة للإنجاز؟', NULL, 153),
  ('4.2.1', 'guidance', 1, 'شمولية الخطة وتضمينها مجموعة متنوعة من البرامج والأنشطة، مثل: العروض الثقافية التقليدية، وورش العمل الفنية، والمسابقات الوطنية، والمعارض التي تبرز التراث والتاريخ.', 1, 155),
  ('4.2.1', 'guidance', 2, 'تعزيز الفخر بالتراث الوطني من خلال الاحتفال بالمناسبات الوطنية والدينية.', 1, 155),
  ('4.2.1', 'guidance', 3, 'تقديم نماذج إيجابية من أفراد المجتمع القطري / الإسلامي ليكونوا قدوة للطلبة.', 1, 155),
  ('4.2.1', 'guidance', 4, 'المبادرات الوطنية، مثل: التي تطلقها وزارة التربية والتعليم أو أي مؤسسة وطنية أخرى.', 1, 155),
  ('4.2.1', 'reflection', 1, 'إلى أي مدى تمتلك المدرسة خطة واضحة ومتكاملة لتعزيز القيم والهوية الوطنية والثقافة القطرية، وكيف يتم تنفيذها ومتابعة أثرها؟', NULL, 155),
  ('4.2.1', 'reflection', 2, 'ما مدى تنوع الأنشطة والبرامج والفعاليات المقدمة، وهل تتناسب مع خصائص واحتياجات مختلف الفئات العمرية والمراحل الدراسية؟', NULL, 155),
  ('4.2.1', 'reflection', 3, 'إلى أي مدى يتم إشراك كافة الطلبة بفاعلية في هذه الأنشطة بما يضمن تكافؤ الفرص وعدم اقتصار المشاركة على فئة محددة؟', NULL, 155),
  ('4.2.1', 'reflection', 4, 'كيف تسهم هذه البرامج والأنشطة في تعزيز فهم الطلبة للهوية الوطنية والقيم، وما الأدلة على ذلك؟', NULL, 155),
  ('4.2.1', 'reflection', 5, 'ما طبيعة الشراكات مع مؤسسات المجتمع، وكيف تدعم هذه الشراكات تحقيق أهداف تعزيز الهوية الوطنية؟', NULL, 155),
  ('4.2.1', 'reflection', 6, 'إلى أي مدى تدعم المدرسة المبادرات الوطنية، وكيف ينعكس ذلك على تنمية روح المواطنة والانتماء لدى الطلبة؟', NULL, 155),
  ('4.2.2', 'guidance', 1, 'تعريف الموظفين والطلبة الجدد بالقيم الإسلامية وعادات وتقاليد المجتمع القطري وقواعد اللبس والمظهر المحتشم.', 1, 156),
  ('4.2.2', 'guidance', 2, 'تخصيص مكان مهيأ، ونظيف، وهادئ لأداء الصلاة وفق الضوابط الشرعية.', 1, 156),
  ('4.2.2', 'guidance', 3, 'إتاحة الوقت الكافي للطلبة المسلمين لأداء الصلاة.', 1, 156),
  ('4.2.2', 'guidance', 4, 'تنوع وجودة أعمال الطلبة التي تتناول موضوعات مرتبطة بالهوية الوطنية والقيم الثقافية والدينية، وتوظيف هذه الأعمال في البيئة المدرسية لتعزيز التعلم البصري وترسيخ القيم.', 1, 156),
  ('4.2.2', 'guidance', 5, 'تطبيق إجراءات منتظمة لرفع العلم القطري وأداء النشيد الوطني، وبمشاركة الطلبة والموظفين، بما يعكس احترام الدولة ورموزها الوطنية.', 1, 156),
  ('4.2.2', 'reflection', 1, 'إلى أي مدى يلتزم الموظفون والطلبة بالمظهر المحتشم الذي يعكس احترام الثقافة القطرية والقيم الإسلامية؟', NULL, 156),
  ('4.2.2', 'reflection', 2, 'إلى أي مدى توفر المدرسة وقتاً ومكاناً مناسبين لإقامة الصلاة، وكيف تضمن انتظام الطلبة والتزامهم بها؟', NULL, 156),
  ('4.2.2', 'reflection', 3, 'إلى أي مدى تعكس أعمال الطلبة والمشاريع المعروضة في الصفوف والمرافق الهوية الوطنية والثقافة القطرية والقيم الإسلامية، وما مستوى جودتها وتنوعها؟', NULL, 156),
  ('4.2.2', 'reflection', 4, 'إلى أي مدى تلتزم المدرسة برفع العلم القطري وأداء النشيد الوطني بانتظام، وما أثر ذلك على تعزيز شعور الطلبة بالفخر والانتماء؟', NULL, 156),
  ('4.2.2', 'reflection', 5, 'إلى أي مدى تحرص المدرسة على عرض صور سمو الأمير والأمير الوالد والرموز الوطنية القطرية بشكلٍ مناسب ومنظّم وواضح، وكيف يسهم ذلك في تعزيز الهوية الوطنية لدى الطلبة؟', NULL, 156),
  ('4.2.3', 'guidance', 1, 'دمج الهوية الوطنية في المنهج: تضمين مفاهيم الهوية الوطنية والثقافة القطرية في الخطط الدراسية والمحتوى التعليمي بطريقة منهجية ومتسقة مع الأهداف التعليمية، بحيث يتم ربط الموضوعات الدراسية بالسياق الوطني والثقافي للطلبة.', 1, 156),
  ('4.2.3', 'guidance', 2, 'تنوع الأنشطة والمشاريع الطلابية، ومستوى مشاركة الطلبة فيها، ومدى ارتباطها بأهداف واضحة تدعم تعزيز الهوية الوطنية.', 1, 157),
  ('4.2.3', 'guidance', 3, 'مراجعة واختيار المصادر والمواد التعليمية المستخدمة داخل المدرسة بما يضمن توافقها مع تعاليم الديني الإسلامي والثقافة القطرية، وخلوها من أي محتوى غير مناسب.', 1, 157),
  ('4.2.3', 'reflection', 1, 'إلى أي مدى يتم دمج مفاهيم الهوية الوطنية والثقافة القطرية بشكلٍ منهجي في الخطط الدراسية والمحتوى التعليمي؟', NULL, 156),
  ('4.2.3', 'reflection', 2, 'كيف ينعكس هذا الدمج في ممارسات التعليم والتعلم داخل الصفوف؟', NULL, 156),
  ('4.2.3', 'reflection', 3, 'ما مدى اتساق تطبيق دمج الهوية الوطنية بين المواد الدراسية المختلفة؟', NULL, 156),
  ('4.2.3', 'reflection', 4, 'إلى أي مدى تنفذ المدرسة أنشطة ومشاريع طلابية تعزز الهوية الوطنية والثقافة المحلية؟', NULL, 157),
  ('4.2.3', 'reflection', 5, 'ما الإجراءات المتبعة لمراجعة واعتماد المواد التعليمية قبل استخدامها؟', NULL, 157),
  ('4.2.3', 'reflection', 6, 'كيف يتم التأكد من خلو المصادر التعليمية مما يخالف التعاليم الدينية والثقافة القطرية؟', NULL, 157),
  ('4.2.3', 'reflection', 7, 'كيف يتم رصد ومعالجة أي محتوى غير مناسب إذا تم اكتشافه؟', NULL, 157),
  ('4.2.4', 'guidance', 1, 'جودة ممارسات التعليم والتعلم: مدى فاعلية وملاءمة الأساليب والاستراتيجيات التي يستخدمها المعلم في تخطيط وتنفيذ وتقويم عملية التعلم، بما يضمن تحقيق نواتج التعلم.', 1, 157),
  ('4.2.4', 'guidance', 2, 'جودة مخرجات تعلم الطلبة: مستوى إتقان الطلبة للمعارف والمهارات والقيم المستهدفة في مواد اللغة العربية، والتربية الإسلامية، والتاريخ القطري والمواطنة، بما يعكس جودة التعلم وفاعلية التدريس.', 1, 157),
  ('4.2.4', 'reflection', 1, 'إلى أي مدى تتميز ممارسات التعليم والتعلم بالفاعلية والجودة في مواد اللغة العربية، والتربية الإسلامية، والتاريخ القطري والمواطنة؟', NULL, 157),
  ('4.2.4', 'reflection', 2, 'ما مدى اتساق جودة الممارسات التعليمية بين المعلمين وفي المراحل الدراسية المختلفة؟', NULL, 157),
  ('4.2.4', 'reflection', 3, 'إلى أي مدى يحقق الطلبة نواتج التعلم المستهدفة في هذه المواد؟', NULL, 157),
  ('4.2.4', 'reflection', 4, 'كيف تعكس أعمال الطلبة وأداؤهم مستوى فهمهم وإتقانهم للمعارف والمهارات؟', NULL, 157),
  ('4.2.4', 'reflection', 5, 'ما مدى تطور أداء الطلبة بمرور الوقت، وما الأدلة على ذلك؟', NULL, 157),
  ('5.1.1', 'guidance', 1, 'سياسة التوظيف: وثيقة تنظيمية تحدد المعايير والإجراءات المتبعة في استقطاب الموظفين واختيارهم وتعيينهم، بما يضمن توفير كفاءات تحقق أهداف المدرسة وجودة الأداء.', 1, 169),
  ('5.1.1', 'guidance', 2, 'وجود لجنة متخصصة أو فريق عمل مسؤول عن متابعة تنفيذ سياسة التوظيف.', 1, 169),
  ('5.1.1', 'guidance', 3, 'وجود سجلات مفصلة تبين مؤهلات الموظفين وخبراتهم المهنية، ومقارنة هذه المعلومات مع متطلبات الوظائف التي يشغلونها.', 1, 169),
  ('5.1.1', 'reflection', 1, 'كيف يتم تحديد الاحتياجات الفعلية من الموارد البشرية في المدرسة؟', NULL, 169),
  ('5.1.1', 'reflection', 2, 'كيف تقوم المدرسة بتحديد معايير الكفاءة المطلوبة لكل وظيفة، سواء كانت تعليمية أو إدارية؟', NULL, 169),
  ('5.1.1', 'reflection', 3, 'كيف تضمن المدرسة أن الأشخاص المعنيين بعملية التوظيف يمتلكون المهارات والمعرفة اللازمة لاختيار أفضل الكوادر؟', NULL, 169),
  ('5.1.1', 'reflection', 4, 'ما الاستراتيجيات التي تعتمدها المدرسة لضمان أن الموظفين المعنيين يتناسبون مع ثقافة المدرسة وقيمها ويدعمون تحقيق رؤيتها ورسالتها؟', NULL, 169),
  ('5.1.1', 'reflection', 5, 'كيف يتم تحديث سياسة التوظيف؟ وما الآليات التي تضمن استجابة هذه السياسة لاحتياجات المدرسة المتغيرة؟', NULL, 169),
  ('5.1.1', 'reflection', 6, 'كم نسبة المعلمين إلى عدد الطلبة؟ وما أثر ذلك على تعلم الطلبة؟', NULL, 169),
  ('5.1.2', 'guidance', 1, 'خطة تدريب الموظفين الجدد: وثيقة تتضمن مجموعة من البرامج والأنشطة التدريبية والتعريفية المخططة للموظفين الجدد، وتشمل عناصر مثل: محتوى التدريب، والجداول الزمنية، وأهداف التعلم لكل برنامج، والفئة المستهدفة.', 1, 170),
  ('5.1.2', 'guidance', 2, 'البرامج التدريبية والتعريفية للموظفين الجدد، مثل: التعريف بسياسات المدرسة وإجراءاتها، والتدريب على مهام الوظيفة، وورش عمل تخصصية، والتعريف برؤية المدرسة ورسالتها وقيمها وثقافتها، والتدريب على الأنظمة الإلكترونية.', 1, 170),
  ('5.1.2', 'reflection', 1, 'كيف يتم تهيئة الموظفين الجدد للعمل بالمدرسة؟ وهل توجد برامج تدريبية مُعدة خصيصاً لهم في بداية عملهم؟', NULL, 170),
  ('5.1.2', 'reflection', 2, 'كيف يتم تصميم هذه البرامج لضمان أن الموظفين الجدد يكتسبون المهارات اللازمة حسب احتياجات كل وظيفة؟', NULL, 170),
  ('5.1.2', 'reflection', 3, 'كيف تقوم المدرسة بتحديد احتياجات التدريب للموظفين الجدد؟', NULL, 170),
  ('5.1.2', 'reflection', 4, 'كيف يتم تقييم فعالية التدريب المقدم للموظفين الجدد؟', NULL, 170),
  ('5.1.2', 'reflection', 5, 'ما هو دور الإرشاد والتوجيه خلال فترة التدريب للموظفين الجدد؟', NULL, 170),
  ('5.1.3', 'guidance', 1, 'تحديد برامج التطوير المهني من خلال عدة مصادر، مثل: المشاهدات الصفية، نتائج تقييم أداء الموظفين، التقييم الذاتي، واحتياجات الأقسام المختلفة، استبانات تحديد الاحتياجات، إضافة إلى أي ممارسات أخرى تعتمدها المدرسة.', 1, 170),
  ('5.1.3', 'guidance', 2, 'خطة التطوير المهني السنوية: وثيقة سنوية تتضمن برامج تدريبية داخلية وخارجية، وتستهدف تطوير مهارات الموظفين الجدد والقدامى.', 1, 170),
  ('5.1.3', 'guidance', 3, 'مستوى المشاركة: توضيح مدى مشاركة الموظفين في البرامج التدريبية، ونسب حضورهم.', 1, 170),
  ('5.1.3', 'guidance', 4, 'آلية تقييم فعالية التدريب: الأساليب المتبعة لقياس فعالية البرامج التدريبية، مثل الاستبانات، والمقابلات، ومتابعة الأداء العملي.', 1, 170),
  ('5.1.3', 'guidance', 5, 'تخصيص جزء من ميزانية المدرسة لبرامج التدريب والتطوير المهني.', 1, 171),
