  ('5.1.3', 'reflection', 2, 'ما أنواع برامج التطوير المهني المقدمة للموظفين؟', NULL, 170),
  ('5.1.3', 'reflection', 3, 'كيف تضمن المدرسة أن خطة التطوير المهني تسهم في تحقيق رؤيتها ورسالتها وأهدافها؟', NULL, 170),
  ('5.1.3', 'reflection', 4, 'كيف يتم تقييم فعالية برامج التطوير المهني؟', NULL, 170),
  ('5.1.3', 'reflection', 5, 'ما الآليات التي يتم من خلالها متابعة تقدم أداء الموظفين بعد مشاركتهم في برامج التطوير المهني؟', NULL, 170),
  ('5.1.3', 'reflection', 6, 'كيف تهيّئ المدرسة بيئة محفّزة للتطوير المهني الذاتي لدى الموظفين، وما الإجراءات التي تتّبعها لدعم ذلك؟', NULL, 170),
  ('5.1.3', 'reflection', 7, 'ما مدى كفاية الميزانية المخصصة لبرامج التطوير المهني في المدرسة؟ وكيف يتم التحقق من ذلك؟', NULL, 171),
  ('5.2.1', 'guidance', 1, 'المرافق المدرسية، مثل: الصفوف الدراسية، والمختبرات، والملاعب، والمكتبات، وقاعات الأنشطة، والساحات المدرسية، ومناطق انتظار الطلبة، والمرافق الصحية.', 1, 172),
  ('5.2.1', 'guidance', 2, 'مناطق انتظار الطلبة: هي الأماكن المخصصة في المدرسة التي يمكن للطلبة الانتظار فيها، في بداية اليوم الدراسي، أو خلال فترات الاستراحة، أو نهاية اليوم الدراسي.', 1, 172),
  ('5.2.1', 'guidance', 3, 'مناطق انتظار الطلبة مريحة وآمنة، ومزودة بأثاث مناسب، ويتم تنظيمها بما يتناسب مع أعداد الطلبة واحتياجاتهم.', 1, 172),
