  ('5.2.4', 'guidance', 1, 'توفر عدد مناسب من معامل الحاسب المجهزة بما يتناسب مع عدد الصفوف وعدد الطلبة وعدد حصص الحاسب في المنهج المطبق.', 1, 175),
  ('5.2.4', 'guidance', 2, 'الأجهزة والبرمجيات التعليمية: هي التجهيزات التقنية والتطبيقات الرقمية التي توفرها المدرسة لدعم تنفيذ المنهج، وتمكين الطلبة من اكتساب المعارف والمهارات المرتبطة بتكنولوجيا المعلومات والعلوم التقنية.', 1, 175),
  ('5.2.4', 'guidance', 3, 'توفر فني معمل أو أكثر بحسب عدد المعامل بالمدرسة.', 1, 175),
  ('5.2.4', 'guidance', 4, 'مناسبة الأثاث وعدد الأجهزة لفئات الطلبة العمرية المختلفة.', 1, 175),
  ('5.2.4', 'guidance', 5, 'يمكن تنفيذ حصص الحاسب في الغرف الصفية باستخدام أجهزة تكنولوجية لوحية أو أجهزة حاسوب محمول توفرها المدرسة، وبما يحقق أهداف التعلم.', 1, 175),
  ('5.2.4', 'reflection', 1, 'إلى أي مدى تتوافر في المدرسة معامل حاسب مجهزة بالأجهزة والبرمجيات التعليمية التي تتوافق مع متطلبات المنهج الدراسي واحتياجات الطلبة؟', NULL, 175),
  ('5.2.4', 'reflection', 2, 'إلى أي مدى تتناسب مساحة معامل الحاسب وتجهيزاتها مع أعداد الطلبة؟', NULL, 175),
