  ('5.2.5', 'guidance', 3, 'يشمل تصميم الملاعب وفق معايير السلامة استخدام أرضيات مرنة وغير زلقة، وتوفير تجهيزات السلامة اللازمة، مثل أنظمة إطفاء الحريق، وأجهزة الإنذار، وصناديق الإسعافات الأولية.', 1, 176),
  ('5.2.5', 'guidance', 4, 'تدريب الطلبة والموظفين على قواعد وإجراءات السلامة داخل الملاعب والقاعات الرياضية.', 1, 176),
