  ('5.2.5', 'reflection', 4, 'كيف تسهم القاعات والملاعب الرياضية في تطوير مهارات الطلبة في مختلف الأنشطة الرياضية؟', NULL, 176),
  ('5.2.5', 'reflection', 5, 'كيف يتم تصميم وتجهيز مناطق اللعب المخصصة لأطفال الروضة بما يضمن سلامتهم ويدعم نموهم؟', NULL, 176),
  ('5.2.5', 'reflection', 6, 'ما الإجراءات المتبعة لضمان الالتزام بمعايير الصحة والسلامة في القاعات والملاعب الرياضية؟', NULL, 176),
  ('5.2.5', 'reflection', 7, 'كيف يتم تهيئة المرافق الرياضية لتمكين الطلبة ذوي الإعاقة من المشاركة في الأنشطة الرياضية؟', NULL, 176),
  ('5.2.6', 'guidance', 1, 'توفير بيئة مريحة وصحية في قاعة الطعام يشمل الأثاث الملائم، والتهوية الجيدة، والإضاءة المناسبة، والنظافة المستمرة.', 1, 177),
  ('5.2.6', 'guidance', 2, 'متابعة المعنيين في المدرسة لجودة وسلامة الأغذية المقدمة بشكلٍ دوري.', 1, 177),
  ('5.2.6', 'guidance', 3, 'تشمل اشتراطات الصحة والسلامة في قاعة الطعام تطبيق معايير النظافة الشخصية للعاملين، وضمان التخزين الآمن للأغذية، وتوفير مياه شرب آمنة، وتنظيف الأسطح والمعدات.', 1, 177),
  ('5.2.6', 'reflection', 1, 'ما الإجراءات المتبعة لضمان توفير بيئة صحية وآمنة داخل قاعات الطعام / المقصف المدرسي؟', NULL, 177),
  ('5.2.6', 'reflection', 2, 'كيف يتم تحديد احتياجات الطلبة الغذائية في المدرسة؟ وما مدى ملاءمة الخيارات الغذائية المقدمة لتلك الاحتياجات؟', NULL, 177),
  ('5.2.6', 'reflection', 3, 'كيف يتم مراقبة جودة الأطعمة المقدمة في المقصف المدرسي للتأكد من مطابقتها للمعايير الصحية؟', NULL, 177),
  ('5.2.6', 'reflection', 4, 'إلى أي مدى يتم إشراك الطلبة وأولياء الأمور في اختيار الأطعمة المقدمة في المقصف المدرسي؟', NULL, 177),
  ('5.2.6', 'reflection', 5, 'كيف يتم تنظيم وقت ومكان تناول الطعام بما يضمن راحة الطلبة ويحد من الازدحام؟', NULL, 177),
  ('5.2.7', 'guidance', 1, 'المرافق التخصصية: هي المرافق التي توفرها المدرسة وفقاً لمتطلبات المنهج المطبق فيها، والتي تستلزم مساحات أو تجهيزات أو بيئات متخصصة لدعم تنفيذه وتحقيق أهدافه، ولا يشمل ذلك المرافق التي أفرد لها هذا الدليل معايير مستقلة.', 1, 177),
  ('5.2.7', 'guidance', 2, 'من أمثلتها: مرافق الروبوت والذكاء الاصطناعي، وقاعات أو استوديوهات الفنون الأدائية، والموسيقى، وورش النجارة والخياطة، والطهي، والاستوديوهات الإعلامية، وغيرها بحسب متطلبات المنهج.', 1, 177),
  ('5.2.7', 'guidance', 3, 'تختلف أنواع المرافق التخصصية ومستوى تجهيزها وعددها ومساحاتها وفقاً لطبيعة المنهج المطبق والمرحلة الدراسية.', 1, 178),
  ('5.2.7', 'reflection', 1, 'إلى أي مدى توفر المدرسة مرافق تخصصية تتناسب مع طبيعة المنهج؟', NULL, 177),
  ('5.2.7', 'reflection', 2, 'إلى أي مدى تم تصميم المرافق التخصصية وتجهيزها بما يتوافق مع متطلبات المنهج؟', NULL, 177),
  ('5.2.7', 'reflection', 3, 'كيف يتم توظيف المرافق التخصصية ضمن الخطط التعليمية والأنشطة المدرسية؟', NULL, 177),
  ('5.2.7', 'reflection', 4, 'ما مدى استفادة الطلبة من المرافق التخصصية في التعلم التطبيقي وتنفيذ المشاريع والأنشطة المرتبطة بالمنهج؟', NULL, 177),
  ('5.2.7', 'reflection', 5, 'كيف تقيس المدرسة أثر استخدام المرافق التخصصية على تعلم الطلبة وتنمية مهاراتهم؟', NULL, 178),
  ('5.2.8', 'guidance', 1, 'تشمل المرافق التخصصية المجهزة للطلبة ذوي الإعاقة مرافق تعليمية وعلاجية مساندة، مثل غرف النشاط الحركي، وغرف العلاج الطبيعي والوظيفي، وغرف النطق واللغة، وغرف التكامل الحسي.', 1, 178),
  ('5.2.8', 'guidance', 2, 'المرافق الصحية مهيأة ومجهزة بما يتناسب مع احتياجات الطلبة ذوي الإعاقة.', 1, 178),
  ('5.2.8', 'guidance', 3, 'تشمل البيئة المدرسية المساندة مساحات وممرات مهيأة، مثل ساحات لعب آمنة، وممرات وصول، ومنحدرات تدعم الحركة والاستقلالية.', 1, 178),
  ('5.2.8', 'reflection', 1, 'كم عدد الطلبة ذوي الإعاقة بالمدرسة؟ وما هي حالاتهم؟', NULL, 178),
  ('5.2.8', 'reflection', 2, 'كم عدد المرافق التخصصية بالمدرسة؟ وكيف يتم التأكد من جاهزيتها لدعم تعلم الطلبة ذوي الإعاقة؟', NULL, 178),
  ('5.2.8', 'reflection', 3, 'ما مدى توافر الأدوات والتقنيات المساندة في المرافق المدرسية لدعم تعلم الطلبة ذوي الإعاقة؟', NULL, 178),
  ('5.2.8', 'reflection', 4, 'كيف تساهم هذه المرافق في تعزيز شمولية التعليم وتمكين الطلبة ذوي الإعاقة من المشاركة في الأنشطة المدرسية؟', NULL, 178),
  ('5.2.8', 'reflection', 5, 'كيف تضمن المدرسة تحديث وتطوير المرافق والتجهيزات بما يتماشى مع المستجدات في مجال تعليم الطلبة ذوي الإعاقة؟', NULL, 178),
  ('5.3.1', 'guidance', 1, 'سياسة الأمن والسلامة: تحدد الإجراءات والتدابير الوقائية التي تهدف إلى الوقاية من المخاطر المحتملة، والحفاظ على سلامة الطلبة والموظفين داخل البيئة المدرسية في كافة الأوقات.', 1, 180),
  ('5.3.1', 'guidance', 2, 'خطة إدارة الأزمات والطوارئ: تتضمن الإجراءات والاستراتيجيات اللازمة للاستجابة السريعة والفورية لمختلف حالات الأزمات والطوارئ، مثل: (الحرائق، الزلازل، تسربات كيميائية، اعتداءات، أو انتشار أمراض).', 1, 180),
  ('5.3.1', 'guidance', 3, 'مخططات الإخلاء: رسومات أو لوحات إرشادية معتمدة توضح مسارات الخروج الآمن ومخارج الطوارئ ونقاط التجمع المعتمدة.', 1, 180),
  ('5.3.1', 'guidance', 4, 'نقاط التجمع: مواقع آمنة ومحددة مسبقاً يتوجه إليها الطلبة والموظفون بعد الإخلاء، بهدف حصر الأفراد والتأكد من سلامتهم وتنظيم الاستجابة للإجراءات الطارئة.', 1, 180),
  ('5.3.1', 'guidance', 5, 'الإخلاء الوهمي: تدريب عملي يحاكي حالات الطوارئ المحتملة، يهدف إلى تدريب الطلبة والموظفين على تنفيذ إجراءات الإخلاء الآمن وفق الأدوار والمسارات المحددة، والتحقق من جاهزية المدرسة وفاعلية خطط السلامة والاستجابة للطوارئ.', 1, 180),
  ('5.3.1', 'guidance', 6, 'الإشراف المستمر على الطلبة: متابعة الطلبة بصورة منتظمة في الصفوف الدراسية والمرافق والساحات المدرسية في مختلف الأوقات مثل: (الاستراحة، الانتقال بين مرافق المدرسة، الدخول والانصراف، استخدام الحافلات المدرسية والسيارات الخاصة) وذلك من قبل العاملين في المدرسة وفق مسؤوليات إشرافية محددة وواضحة.', 1, 181),
  ('5.3.1', 'reflection', 1, 'ما السياسات والخطط المتوفرة لضمان أمن وسلامة المجتمع المدرسي؟', NULL, 180),
  ('5.3.1', 'reflection', 2, 'كيف تضمن المدرسة جاهزية العاملين للاستجابة الفعالة للأزمات والطوارئ؟', NULL, 180),
  ('5.3.1', 'reflection', 3, 'ما مدى توافر وصيانة أنظمة السلامة، مثل أجهزة الإنذار وطفايات الحريق، وجاهزيتها للاستخدام عند الحاجة؟', NULL, 180),
  ('5.3.1', 'reflection', 4, 'إلى أي مدى تسهم تدريبات الإخلاء الوهمي في رفع جاهزية الطلبة والموظفين للتعامل مع حالات الطوارئ؟', NULL, 180),
  ('5.3.1', 'reflection', 5, 'كم مرة نفذت المدرسة تدريبات الإخلاء الوهمي خلال العام الدراسي، وما مدى التزام الطلبة والموظفين بإجراءات الإخلاء الآمن؟', NULL, 180),
  ('5.3.1', 'reflection', 6, 'كيف تستفيد المدرسة من نتائج تدريبات الإخلاء الوهمي في تحسين إجراءات الأمن والسلامة؟', NULL, 180),
  ('5.3.1', 'reflection', 7, 'كيف تضمن المدرسة الإشراف المستمر على الطلبة في كافة البيئات المدرسية؟', NULL, 180),
  ('5.3.1', 'reflection', 8, 'ما مدى فاعلية الإجراءات المتبعة لتنظيم دخول وخروج الطلبة والموظفين، والزوار وضمان أمنهم وسلامتهم؟', NULL, 180),
  ('5.3.1', 'reflection', 9, 'كيف تتحقق المدرسة من سلامة الطلبة أثناء استخدام الحافلات المدرسية، وما مدى الالتزام بالإجراءات المعتمدة في هذا الشأن؟ (إن وجدت)', NULL, 181),
  ('5.3.1', 'reflection', 10, 'ما الأدلة التي تشير إلى وعي الموظفين والطلبة وأولياء الأمور والزوار بإجراءات الأمن والسلامة المطبقة في المدرسة؟', NULL, 181),
  ('5.3.2', 'guidance', 1, 'تحدد السياسة الضوابط والمسؤوليات والإجراءات اللازمة لحماية بيانات الطلبة والموظفين، وتنظيم الاستخدام الآمن للأنظمة والموارد الرقمية.', 1, 181),
  ('5.3.2', 'guidance', 2, 'أنظمة الحماية التقنية: الأدوات والبرمجيات والإجراءات التقنية المعتمدة لحماية الشبكات والأنظمة والبيانات المدرسية من الاختراق أو التلف أو سوء الاستخدام، مثل: برامج مكافحة الفيروسات والبرمجيات الخبيثة، أنظمة جدران الحماية (Firewall).', 1, 181),
  ('5.3.2', 'guidance', 3, 'الحوادث الرقمية: أي أحداث غير مخطط لها تؤثر، أو قد تؤثر، في أمن الأنظمة أو البيانات أو الخدمات الرقمية، مثل الاختراقات، أو تسريب البيانات، أو البرمجيات الخبيثة، أو تعطل الخدمات الرقمية.', 1, 181),
  ('5.3.2', 'guidance', 4, 'السلامة الرقمية والاستخدام المسؤول للتقنيات الرقمية: الممارسات والسلوكيات الآمنة والأخلاقية عند استخدام التقنيات الرقمية، وتشمل حماية الخصوصية، والسلوك الرقمي المسؤول، والاستخدام الأخلاقي للتقنيات.', 1, 182),
  ('5.3.2', 'reflection', 1, 'ما هي السياسة والإجراءات المعتمدة لدى المدرسة لحماية البيانات والأمن الرقمي، وكيف يتم تطبيقها ومراجعتها؟', NULL, 181),
  ('5.3.2', 'reflection', 2, 'ما أنظمة الحماية التقنية المتوفرة في المدرسة، وكيف يتم ضمان تحديثها وصيانتها بشكلٍ دوري؟', NULL, 181),
  ('5.3.2', 'reflection', 3, 'كيف يتم التأكد من فاعلية أنظمة الحماية في حماية الشبكات والبيانات؟', NULL, 181),
  ('5.3.2', 'reflection', 4, 'كيف يتم تحديد صلاحيات الوصول للأنظمة والبيانات؟', NULL, 181),
  ('5.3.2', 'reflection', 5, 'ما البرامج أو الأنشطة التوعوية التي تنفذها المدرسة للطلبة والموظفين حول السلامة الرقمية، وكيف يتم قياس أثرها؟', NULL, 181),
  ('5.3.2', 'reflection', 6, 'ما آلية الإبلاغ عن الحوادث الرقمية داخل المدرسة، وما الإجراءات المتبعة للاستجابة لها ومعالجتها؟', NULL, 182),
  ('5.3.3', 'guidance', 1, 'المستلزمات والأدوات الطبية: المواد والأدوات التي تُستخدم لتقديم الرعاية الأولية والعلاجية للطلبة في حالات الطوارئ أو الإصابات البسيطة، مثل: مسكنات الألم، والضمادات، وأدوات قياس الحرارة.', 1, 182),
  ('5.3.3', 'guidance', 2, 'خدمات الرعاية الصحية الشاملة لا تقتصر على الإسعافات الأولية فقط، بل تشمل المتابعة، والوقاية، والتثقيف الصحي، وإدارة الأمراض المزمنة، إلخ.', 1, 182),
  ('5.3.3', 'guidance', 3, 'لا يتضمن هذا المعيار تقديم خدمات طبية علاجية أو تشخيصية متخصصة، إلا في حدود الإجراءات الصحية الأساسية المصرح بها للمدارس من الجهات المختصة وبالتنسيق مع أولياء الأمور.', 1, 182),
  ('5.3.3', 'guidance', 4, 'الحالات المرضية الخاصة: الحالات الصحية التي تتطلب رعاية طبية أو احتياطات محددة داخل المدرسة لضمان سلامة الطلبة، مثل: السكري، والربو، والحساسية الشديدة.', 1, 183),
  ('5.3.3', 'guidance', 5, 'متابعة خدمات التغذية: الإشراف المنتظم على جودة وسلامة الأطعمة والمشروبات المقدمة للطلبة داخل المدرسة.', 1, 183),
  ('5.3.3', 'guidance', 6, 'متابعة جودة مياه الشرب: إجراءات دورية تهدف إلى ضمان سلامة مياه الشرب في المدرسة من خلال الفحص والتنظيف والصيانة، لضمان توافقها مع المعايير الصحية المعتمدة.', 1, 183),
  ('5.3.3', 'reflection', 1, 'إلى أي مدى تتوافر في المدرسة وحدة عناية صحية مرخصة ومجهزة؟', NULL, 182),
  ('5.3.3', 'reflection', 2, 'كيف تتأكد المدرسة من أن حجم وتنظيم وحدة العناية الصحية يتناسب مع أعداد الطلبة وأعمارهم وتنوعهم؟', NULL, 182),
  ('5.3.3', 'reflection', 3, 'ما مدى توفر ممرض مؤهل ومرخص لتقديم الخدمات الصحية؟', NULL, 182),
  ('5.3.3', 'reflection', 4, 'إلى أي مدى تلتزم المدرسة بتقديم الخدمات الصحية وفق إرشادات الجهات المختصة؟', NULL, 182),
  ('5.3.3', 'reflection', 5, 'ما الحالات المرضية الخاصة للطلبة؟ وكيف يتم متابعتها؟', NULL, 182),
  ('5.3.3', 'reflection', 6, 'كيف يتم التواصل مع أولياء الأمور بشأن الحالات الصحية للطلبة؟', NULL, 182),
  ('5.3.3', 'reflection', 7, 'ما مدى جاهزية العاملين للتعامل مع الحالات الصحية الطارئة؟', NULL, 182),
  ('5.3.3', 'reflection', 8, 'ما البرامج التوعوية الصحية التي تم تقديمها في المدرسة؟ وإلى أي مدى تسهم في رفع وعي الطلبة؟', NULL, 183),
  ('5.3.3', 'reflection', 9, 'كيف تتم متابعة جودة مياه الشرب وخدمات التغذية المقدمة في المدرسة؟', NULL, 183),
  ('5.3.4', 'guidance', 1, 'سجلات فحوصات المرافق: سجلات تحتوي على نتائج الفحوصات الدورية للمرافق المدرسية، مثل حالة الصفوف الدراسية، والحمامات، والملاعب، والمرافق العامة.', 1, 183),
  ('5.3.4', 'guidance', 2, 'تقارير صيانة دورية: تقارير توضح حالة المرافق المدرسية، وأعمال الصيانة والإصلاح المنفذة.', 1, 183),
  ('5.3.4', 'guidance', 3, 'الصيانة الوقائية: إجراءات دورية مجدولة تهدف إلى الحفاظ على سلامة المبنى المدرسي ومرافقه، والحد من الأعطال.', 1, 183),
  ('5.3.4', 'guidance', 4, 'وجود اتفاقيات أو عقود رسمية مع شركات صيانة متخصصة.', 1, 184),
  ('5.3.4', 'reflection', 1, 'ما الإجراءات المتبعة لضمان صيانة المبنى المدرسي ومرافقه، والأثاث والأجهزة والمعدات؟', NULL, 183),
  ('5.3.4', 'reflection', 2, 'إلى أي مدى يتم إصلاح الأعطال الطارئة بسرعة وفعالية دون التأثير على سير العملية التعليمية؟ وما الأدلة على ذلك؟', NULL, 183),
  ('5.3.4', 'reflection', 3, 'ما مدى فاعلية التنسيق مع شركات صيانة متخصصة لضمان جودة الخدمات المقدمة؟', NULL, 183),
  ('5.3.4', 'reflection', 4, 'إلى أي مدى تسهم إجراءات الصيانة الوقائية في الحد من الأعطال وضمان استدامة المرافق المدرسية؟', NULL, 183),
  ('5.3.5', 'guidance', 1, 'استخدام أدوات ومواد تنظيف صديقة للبيئة وآمنة، وخالية من المواد الكيميائية الضارة.', 1, 184),
  ('5.3.5', 'guidance', 2, 'تخزين أدوات ومواد التنظيف في أماكن آمنة وبعيدة عن متناول الطلبة.', 1, 184),
  ('5.3.5', 'guidance', 3, 'النفايات المدرسية، مثل: النفايات الورقية والبلاستيكية والكيميائية والبيولوجية، إضافةً إلى الأدوات المدرسية القديمة أو التالفة.', 1, 184),
  ('5.3.5', 'guidance', 4, 'التعاقد مع شركات متخصصة في جمع النفايات والتخلص منها وفقاً للمعايير المعتمدة، ومكافحة الحشرات والقوارض، وتنظيف المبنى والمرافق المدرسية.', 1, 184),
  ('5.3.5', 'reflection', 1, 'ما الإجراءات المتبعة لضمان نظافة المبنى المدرسي والمرافق والأثاث؟ وما مدى فعالية هذه الإجراءات؟', NULL, 184),
  ('5.3.5', 'reflection', 2, 'كيف يتم التحقق من مستوى النظافة في كافة مرافق ومناطق المدرسة؟', NULL, 184),
